set search_path = public, private, extensions;
select plan(9);
insert into public.users(id, display_name) values ('b9999999-9999-4999-8999-999999999992', 'Invoice test owner');
insert into public.workspaces(id, name, creator_id, personal) values ('b9999999-9999-4999-8999-999999999991', 'Invoice test workspace', 'b9999999-9999-4999-8999-999999999992', false);
select private.record_external_provider_invoice('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','neon','dedicated','test-invoice','2026-01-01','2026-01-02',1.25);
select private.record_external_provider_invoice('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','neon','dedicated','test-invoice','2026-01-01','2026-01-02',1.25);
select is((select count(*)::int from private.get_external_provider_invoices('b9999999-9999-4999-8999-999999999991')),1,'retries retain one invoice');
select throws_ok($$select private.record_external_provider_invoice('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','neon','dedicated','test-invoice','2026-01-01','2026-01-02',2)$$,'23505',null,'conflicting invoice rejected');
select is((select amount_usd from private.get_external_provider_invoices('b9999999-9999-4999-8999-999999999991')),1.25::numeric,'original retained');
select is((select count(*)::int from private.get_external_provider_invoices('b9999999-9999-4999-8999-999999999992')),0,'workspace isolated');
select is((select count(*)::int from private.get_external_provider_costs('b9999999-9999-4999-8999-999999999991','2026-01-01','2026-02-01')),0,'invoices do not inflate metered usage');
select ok(not has_table_privilege('authenticated','private.external_provider_invoices','SELECT'),'session cannot bypass authorization');
select ok(not has_table_privilege('service_role','private.external_provider_invoices','UPDATE'),'receipt immutable');
select ok(not has_function_privilege('anon','private.record_external_provider_invoice(uuid,text,uuid,text,text,text,date,date,numeric)','EXECUTE'),'anonymous cannot write');
select throws_ok($$select private.record_external_provider_invoice('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','neon','dedicated','negative','2026-01-01','2026-01-02',-1)$$,'23514',null,'negative rejected');
select * from finish();
rollback;
